import os, json
d = os.environ.get('RLM_SESSION_DIR', '')
log_path = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
content = open(log_path).read()

# Load and parse JSONL
lines = content.split('\n')
print(f"Total lines: {len(lines)}")

# Look for message content
msg_count = 0
for line in lines:
    if line.startswith('{"type":"message"'):
        msg_count += 1
        # Try to extract text content
        try:
            m = json.loads(line)
            if 'message' in m and 'content' in m['message']:
                for c in m['message']['content']:
                    if 'text' in c:
                        text = c['text']
                        if 'Demo pair' in text:
                            # Print context
                            print(f"Found Demo pair reference...")
                            print(text[:2000])
        except:
            pass

print(f"\nTotal message count: {msg_count}")

